import pytest
from unittest.mock import patch
from pylint.message._deleted_message_ids import is_deleted_msgid

class TestIsDeletedMsgid:
    @patch('pylint.message._deleted_message_ids.DELETED_MESSAGES_IDS')
    def test_msgid_found_in_deleted_messages(self, mock_deleted_messages):
        # Arrange
        mock_deleted_messages.items.return_value = [
            ("This message was removed due to redundancy", [
                type('MockMessage', (), {'msgid': 'C0103', 'old_names': []})(),
                type('MockMessage', (), {'msgid': 'C0104', 'old_names': []})()
            ]),
            ("This message was deprecated", [
                type('MockMessage', (), {'msgid': 'W0613', 'old_names': []})()
            ])
        ]

        # Act
        result = is_deleted_msgid('C0103')

        # Assert
        assert result == "This message was removed due to redundancy"

    @patch('pylint.message._deleted_message_ids.DELETED_MESSAGES_IDS')
    def test_msgid_found_in_old_names(self, mock_deleted_messages):
        # Arrange
        mock_deleted_messages.items.return_value = [
            ("This message was replaced", [
                type('MockMessage', (), {'msgid': 'R0903', 'old_names': [('old-id-1', 'OLD001')]})()
            ])
        ]

        # Act
        result = is_deleted_msgid('OLD001')

        # Assert
        assert result == "This message was replaced"

    @patch('pylint.message._deleted_message_ids.DELETED_MESSAGES_IDS')
    def test_msgid_not_found(self, mock_deleted_messages):
        # Arrange
        mock_deleted_messages.items.return_value = [
            ("Some deletion reason", [
                type('MockMessage', (), {'msgid': 'C0103', 'old_names': []})()
            ])
        ]

        # Act
        result = is_deleted_msgid('NONEXISTENT')

        # Assert
        assert result is None

    @patch('pylint.message._deleted_message_ids.DELETED_MESSAGES_IDS')
    def test_empty_deleted_messages(self, mock_deleted_messages):
        # Arrange
        mock_deleted_messages.items.return_value = []

        # Act
        result = is_deleted_msgid('ANY_ID')

        # Assert
        assert result is None

    @patch('pylint.message._deleted_message_ids.DELETED_MESSAGES_IDS')
    def test_multiple_entries_with_matching_msgid(self, mock_deleted_messages):
        # Arrange
        mock_deleted_messages.items.return_value = [
            ("First reason", [
                type('MockMessage', (), {'msgid': 'DUPLICATE', 'old_names': []})()
            ]),
            ("Second reason", [
                type('MockMessage', (), {'msgid': 'DUPLICATE', 'old_names': []})()
            ])
        ]

        # Act
        result = is_deleted_msgid('DUPLICATE')

        # Assert
        assert result == "First reason"  # Should return the first match

    @patch('pylint.message._deleted_message_ids.DELETED_MESSAGES_IDS')
    def test_old_names_containing_multiple_entries(self, mock_deleted_messages):
        # Arrange
        mock_deleted_messages.items.return_value = [
            ("Complex deprecation", [
                type('MockMessage', (), {
                    'msgid': 'COMPLEX',
                    'old_names': [('legacy-1', 'LEG001'), ('legacy-2', 'LEG002')]
                })()
            ])
        ]

        # Act & Assert
        result1 = is_deleted_msgid('LEG001')
        result2 = is_deleted_msgid('LEG002')

        assert result1 == "Complex deprecation"
        assert result2 == "Complex deprecation"

